/**
 * @name Code injection via exec with tainted input
 * @description Using exec with untrusted input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/exec-code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module ExecInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Remote flow sources
    source instanceof RemoteFlowSource
    or
    // Function parameters that could be user-controlled
    source instanceof DataFlow::ParameterNode
    or
    // Attribute access that could be external input
    exists(DataFlow::AttrRead attr |
      source = attr and
      not attr.getAttributeName() in ["__name__", "__module__", "__qualname__", "__class__"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(CodeExecution ce).getCode()
  }
}

module ExecInjectionFlow = TaintTracking::Global<ExecInjectionConfig>;
import ExecInjectionFlow::PathGraph

from ExecInjectionFlow::PathNode source, ExecInjectionFlow::PathNode sink
where ExecInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "exec() call with potentially untrusted input from $@.", source.getNode(), "this source"
